def choose_move(observation):
    # Defensive defaults
    pos = observation.get("position", {})
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    # Initialize with no movement
    dx = 0
    dy = 0

    # Consider resource_collection: try to move toward nearest resource if available
    resources = observation.get("resources", [])
    if isinstance(resources, list) and resources:
        # Find closest resource by Manhattan distance
        best = None
        best_dist = float('inf')
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            dist = abs(rx - x) + abs(ry - y)
            if dist < best_dist:
                best_dist = dist
                best = (rx, ry)
        if best is not None:
            rx, ry = best
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1
            # If both axes set, fine; otherwise keep zero on that axis

    # If no resources or not moved toward one, attempt pursuit_evasion style: chase nearest agent
    if dx == 0 and dy == 0:
        opponents = observation.get("opponents", [])
        if isinstance(opponents, list) and opponents:
            best = None
            best_dist = float('inf')
            for o in opponents:
                ox = o.get("x", 0)
                oy = o.get("y", 0)
                dist = abs(ox - x) + abs(oy - y)
                if dist < best_dist:
                    best_dist = dist
                    best = (ox, oy)
            if best is not None:
                ox, oy = best
                if ox > x:
                    dx = 1
                elif ox < x:
                    dx = -1
                if oy > y:
                    dy = 1
                elif oy < y:
                    dy = -1

    # If still idle, prefer staying or small exploration: move toward origin (0,0) modestly
    if dx == 0 and dy == 0:
        if x > 0:
            dx = -1
        elif x < 0:
            dx = 1
        if y > 0:
            dy = -1
        elif y < 0:
            dy = 1

    # Bound to -1, 0, 1 by construction
    return [dx, dy]

